/* prog44_miller_rabin.c
 *
 * Re‑implementation of the original binary's observable behaviour.
 * It reads a single decimal integer from the command line and prints
 * one of the messages described above.
 *
 * The implementation follows the logic uncovered in the disassembly:
 *   - argument handling,
 *   - range check (max 0xBFA17DC6),
 *   - deterministic Miller–Rabin with bases {2,3,5,7,11,13}.
 *
 * The program is fully self‑contained and compiles with a standard C
 * compiler (C99 or later).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>
#include <errno.h>

/* Fixed upper bound used by the original binary */
#define MAX_VALUE 0xBFA17DC6ULL

/* Bases used for the deterministic Miller–Rabin test on 32‑bit numbers */
static const uint64_t bases[] = {2, 3, 5, 7, 11, 13};
static const size_t n_bases = sizeof(bases) / sizeof(bases[0]);

/* 64‑bit modular multiplication – uses __uint128_t to avoid overflow */
static uint64_t mul_mod(uint64_t a, uint64_t b, uint64_t mod)
{
    __uint128_t prod = ( __uint128_t ) a * b;
    return (uint64_t)(prod % mod);
}

/* 64‑bit modular exponentiation (binary exponentiation) */
static uint64_t pow_mod(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t result = 1;
    base %= mod;
    while (exp) {
        if (exp & 1)
            result = mul_mod(result, base, mod);
        base = mul_mod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

/* Miller–Rabin test for a single base.
   Returns 1 if n passes this base (i.e. is *probably* prime),
   0 if the base proves n is composite. */
static int miller_rabin_pass(uint64_t n, uint64_t a)
{
    if (a % n == 0)               /* a == n (handled earlier) */
        return 1;

    /* write n‑1 = d·2^s with d odd */
    uint64_t d = n - 1;
    unsigned int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }

    uint64_t x = pow_mod(a, d, n);
    if (x == 1 || x == n - 1)
        return 1;

    for (unsigned int r = 1; r < s; ++r) {
        x = mul_mod(x, x, n);
        if (x == n - 1)
            return 1;
    }
    return 0;   /* composite */
}

/* Full deterministic Miller–Rabin for the range used by the binary */
static int is_prime(uint64_t n)
{
    if (n < 2)
        return 0;

    /* Quick trial division by the small bases.
       This also catches the case n == base, which is prime. */
    for (size_t i = 0; i < n_bases; ++i) {
        uint64_t p = bases[i];
        if (n == p)
            return 1;
        if (n % p == 0)
            return 0;
    }

    /* Miller–Rabin with the same bases */
    for (size_t i = 0; i < n_bases; ++i) {
        if (!miller_rabin_pass(n, bases[i]))
            return 0;
    }
    return 1;
}

int main(int argc, char *argv[])
{
    /* 1. No argument */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* 2. Parse the argument */
    char *endptr = NULL;
    errno = 0;
    uint64_t n = strtoull(argv[1], &endptr, 10);

    /* BAD_INPUT only when *no* characters were consumed */
    if (errno != 0 || endptr == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }

    /* 3. Range check */
    if (n > MAX_VALUE) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* 4. Primality test */
    if (is_prime(n))
        puts("PRIME");
    else
        puts("NOT_PRIME");

    return 0;
}
